/**
 * sanitizeHtml.js — Resilient Stored XSS Prevention for Rich Text Content
 * 
 * Safely parses HTML and strips malicious tags, event handlers, and entity-encoded
 * pseudo-protocols using sanitize-html, while preserving valid semantic HTML
 * generated by rich-text editors (headings, paragraphs, lists, tables, images, links).
 */
import sanitizeHtml from "sanitize-html";

export const DEFAULT_SANITIZE_OPTIONS = {
  allowedTags: [
    "h1", "h2", "h3", "h4", "h5", "h6",
    "p", "br", "hr",
    "strong", "b", "em", "i", "u", "s", "strike", "blockquote",
    "code", "pre",
    "ul", "ol", "li",
    "a",
    "table", "thead", "tbody", "tfoot", "tr", "th", "td",
    "figure", "figcaption",
    "span", "div",
    "img",
    "sub", "sup"
  ],
  allowedAttributes: {
    a: ["href", "name", "target", "rel", "title"],
    img: ["src", "alt", "title", "width", "height", "loading"],
    table: ["border", "cellpadding", "cellspacing"],
    th: ["colspan", "rowspan", "scope", "align"],
    td: ["colspan", "rowspan", "align"],
    "*": ["class", "id"]
  },
  allowedSchemes: ["http", "https", "mailto", "tel"],
  allowedSchemesByTag: {
    img: ["http", "https", "data"]
  },
  transformTags: {
    a: (tagName, attribs) => {
      const rels = (attribs.rel || "").split(/\s+/).filter(Boolean);
      if (!rels.includes("noopener")) rels.push("noopener");
      if (!rels.includes("noreferrer")) rels.push("noreferrer");
      return {
        tagName: "a",
        attribs: {
          ...attribs,
          rel: rels.join(" ")
        }
      };
    }
  }
};

/**
 * Strips executable or dangerous HTML elements from user-submitted rich content.
 * Defends against stored XSS including entity-encoded pseudo-protocol bypasses.
 * 
 * @param {string} html Raw user HTML
 * @param {object} [customOptions] Optional sanitize-html configuration overrides
 * @returns {string} Clean, safe HTML string
 */
export function sanitizeRichHtml(html, customOptions = {}) {
  if (typeof html !== "string") return "";

  // Strip control characters (except tab, newline, carriage return)
  const cleaned = html.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, "");

  const options = {
    ...DEFAULT_SANITIZE_OPTIONS,
    ...customOptions,
    allowedTags: customOptions.allowedTags || DEFAULT_SANITIZE_OPTIONS.allowedTags,
    allowedAttributes: customOptions.allowedAttributes || DEFAULT_SANITIZE_OPTIONS.allowedAttributes,
    allowedSchemes: customOptions.allowedSchemes || DEFAULT_SANITIZE_OPTIONS.allowedSchemes,
    transformTags: customOptions.transformTags || DEFAULT_SANITIZE_OPTIONS.transformTags
  };

  return sanitizeHtml(cleaned, options).trim();
}

export default sanitizeRichHtml;
